    local P = self.text
    P.i = P.i % #P.txt + 1
    local t = P.txt[P.i]
    t:stop()
    local ec = K.elementColor[element] or WHITE
    local s = tostring(value)
    if label then s = label end
    local size = label and 44 or (big and 40 or 30)
    t:text(s):font(size, 'c'):size(400, 70):pos(x + (self:rand() - 0.5) * 60, y):scale(label and 0.6 or 0.8)
    t:color(ec[1], ec[2], ec[3], 255):outline(20, 14, 30, 255):on(true)
    t:front()
    t.ty = y + (label and 90 or 70)
    t:tween({anchoredPositionY = t.ty, localScaleX = 1, localScaleY = 1}, 0.25, 'OutBack')
    local app = self.app
    t.fadeAt = app.t + (hold or (label and 0.9 or 0.6))
