            fx:dust(p.x / C, 0, false)
            fx:wind(p.x / C, p.y / C, e.back and -p.face or p.face, p.element)
            au:play(au.ID.dash)
        elseif ty == 'jump' then
            local p = sim.f[e.p]
            fx:dust(p.x / C, 0, false)
            au:play(au.ID.jump)
        elseif ty == 'land' then
