    if self.bd then self.bd:step(300) end
    if self.app:isMobile() and self.items[1] and self.items[1].id=='quality' then self.app:go('options');return end
    self.menu:input(self.app.input:menu())
end

local INFO = {
    quality = {'QUALITY', '画质', '默认简单画质。电脑可切换高级画质，读条后重新加载更细的角色拟合与背景；手机固定简单画质。'},
